CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, guest_token uuid NOT NULL DEFAULT gen_random_uuid(), email text NOT NULL, name text NOT NULL, address text NOT NULL, postcode text NOT NULL, items jsonb NOT NULL, total numeric(10,2) NOT NULL, status text NOT NULL DEFAULT 'enquiry', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.orders TO anon, authenticated;
GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Customers see own orders" ON public.orders FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Customers create own orders" ON public.orders FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND total >= 0);
CREATE POLICY "Guests create orders" ON public.orders FOR INSERT TO anon WITH CHECK (user_id IS NULL AND total >= 0);
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, product_slug text NOT NULL, rating int NOT NULL CHECK (rating BETWEEN 1 AND 5), comment text NOT NULL, approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.reviews TO anon, authenticated;
GRANT ALL ON public.reviews TO service_role;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Approved reviews are public" ON public.reviews FOR SELECT TO anon, authenticated USING (approved = true OR user_id = auth.uid());
CREATE POLICY "Members submit reviews" ON public.reviews FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND approved = false);
CREATE TABLE public.mailing_list (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.mailing_list TO anon, authenticated;
GRANT ALL ON public.mailing_list TO service_role;
ALTER TABLE public.mailing_list ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Visitors subscribe" ON public.mailing_list FOR INSERT TO anon, authenticated WITH CHECK (length(email) > 3);
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TRIGGER orders_updated_at BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER reviews_updated_at BEFORE UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER mailing_list_updated_at BEFORE UPDATE ON public.mailing_list FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();